    public static function canonicalUrl(string $input): string
    {
        $raw = trim($input);
        if ($raw === '') { throw new \InvalidArgumentException('path required'); }
        if (str_contains($raw, '\\') || str_contains($raw, '%')) { throw new \InvalidArgumentException('invalid path'); }
        $hash = strpos($raw, '#');
        if ($hash !== false) { $raw = substr($raw, 0, $hash); }
        $query = strpos($raw, '?');
        if ($query !== false) { $raw = substr($raw, 0, $query); }
        $lower = strtolower($raw);
        if (str_starts_with($lower, 'https://') || str_starts_with($lower, 'http://') || str_starts_with($raw, '//')) {
            $rest = str_starts_with($lower, 'https://') ? substr($raw, 8) : (str_starts_with($lower, 'http://') ? substr($raw, 7) : substr($raw, 2));
            $slash = strpos($rest, '/');
            $hostport = $slash === false ? $rest : substr($rest, 0, $slash);
            $path = $slash === false ? '/' : substr($rest, $slash);
            if (str_contains($hostport, '@')) { throw new \InvalidArgumentException('userinfo not allowed'); }
            if (str_contains($hostport, ':')) { throw new \InvalidArgumentException('port not allowed'); }
            if (strtolower($hostport) !== self::HOST) { throw new \InvalidArgumentException('host not allowed'); }
        } elseif (str_starts_with($raw, '/')) {
            $path = $raw;
        } else {
            $path = '/' . $raw;
        }
        while (str_contains($path, '//')) { $path = str_replace('//', '/', $path); }
        $path = strtolower($path);
        foreach (explode('/', $path) as $seg) {
            if ($seg === '.' || $seg === '..') { throw new \InvalidArgumentException('path traversal'); }
        }
        if (strlen($path) > 1) { $path = rtrim($path, '/'); }
        if ($path === '') { $path = '/'; }
        if (!isset(self::PATHS[$path])) { throw new \InvalidArgumentException('unknown path: ' . $path); }
        return $path === '/' ? self::ORIGIN . '/' : self::ORIGIN . $path;
    }

    private static function resolve(string $name): string
    {
        if (isset(self::PAGES[$name])) { return self::PAGES[$name]; }
        if (isset(self::BLOGS[$name])) { return self::BLOGS[$name]; }
        if (isset(self::BASE[$name])) { return $name; }
        throw new \InvalidArgumentException('unknown page: ' . $name);
    }

    public static function homeUrl(): string { return self::canonicalUrl('/'); }
    public static function pageUrl(string $name): string { return self::canonicalUrl(self::resolve($name)); }
    public static function blogUrl(string $slug): string
    {
        if (!isset(self::BLOGS[$slug])) { throw new \InvalidArgumentException('unknown blog: ' . $slug); }
        return self::canonicalUrl(self::BLOGS[$slug]);
    }
    public static function localeUrl(string $locale, string $name): string
    {
        if (!isset(self::LOCALES[$locale])) { throw new \InvalidArgumentException('unknown locale: ' . $locale); }
        $path = self::resolve($name);
        if ($locale === 'en') { return self::canonicalUrl($path); }
        return self::canonicalUrl($path === '/' ? '/' . $locale : '/' . $locale . $path);
    }
